ALTER TABLE "user" ADD COLUMN IF NOT EXISTS password_change_required integer NOT NULL DEFAULT 0;
ALTER TABLE "user" ADD COLUMN IF NOT EXISTS last_login_at timestamp;
ALTER TABLE "user" ADD COLUMN IF NOT EXISTS login_failure_count integer NOT NULL DEFAULT 0;
ALTER TABLE "user" ADD COLUMN IF NOT EXISTS locked_until timestamp;
ALTER TABLE "user" ADD COLUMN IF NOT EXISTS password_changed_at timestamp;
ALTER TABLE "group" ADD COLUMN IF NOT EXISTS status varchar NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE group_member ADD COLUMN IF NOT EXISTS removed_at timestamp;
CREATE UNIQUE INDEX IF NOT EXISTS uq_group_setting_group_key ON group_setting(group_id,key);
CREATE TABLE IF NOT EXISTS payment_method(id varchar PRIMARY KEY,group_id varchar NOT NULL REFERENCES "group"(group_id) ON UPDATE CASCADE ON DELETE CASCADE,payment_no integer NOT NULL,payment_name varchar NOT NULL,disabled_flag integer NOT NULL DEFAULT 0,create_date timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,update_date timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS uq_payment_method_group_name ON payment_method(group_id,payment_name);
CREATE TABLE IF NOT EXISTS purchase_pattern(id varchar PRIMARY KEY,group_id varchar NOT NULL REFERENCES "group"(group_id) ON UPDATE CASCADE ON DELETE CASCADE,pattern_type varchar NOT NULL,display_no integer NOT NULL,display_name varchar NOT NULL,category_ids text,payment_method_ids text,member_ids text,label_ids text,transaction_type varchar,amount bigint,settlement_status varchar,date_from date,date_to date,note varchar,disabled_flag integer NOT NULL DEFAULT 0,auto_disabled integer NOT NULL DEFAULT 0,create_date timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,update_date timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE purchase_pattern ADD COLUMN IF NOT EXISTS amount_from bigint;
ALTER TABLE purchase_pattern ADD COLUMN IF NOT EXISTS amount_to bigint;
CREATE UNIQUE INDEX IF NOT EXISTS uq_purchase_pattern_group_type_name ON purchase_pattern(group_id,pattern_type,lower(display_name));
CREATE TABLE IF NOT EXISTS kanban_card(id varchar PRIMARY KEY,group_id varchar NOT NULL REFERENCES "group"(group_id) ON UPDATE CASCADE ON DELETE CASCADE,title varchar(100) NOT NULL,content text,status varchar(20) NOT NULL DEFAULT 'TODO',display_no integer NOT NULL DEFAULT 1,color varchar(20) NOT NULL DEFAULT 'YELLOW',created_by varchar,create_date timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,update_date timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_kanban_card_group_status_order ON kanban_card(group_id,status,display_no);
ALTER TABLE shopping ADD COLUMN IF NOT EXISTS payment_method_id varchar;
ALTER TABLE shopping ADD COLUMN IF NOT EXISTS shopping_label_ids text;
CREATE INDEX IF NOT EXISTS idx_shopping_group_date ON shopping(group_id,shopping_date);
CREATE TABLE IF NOT EXISTS operation_log(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id varchar,method varchar NOT NULL,path varchar NOT NULL,status integer NOT NULL,action varchar,target_id varchar,detail varchar,request_id varchar,ip_address varchar,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_setting(key varchar PRIMARY KEY,value varchar,description varchar,updated_by varchar,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_state(id integer PRIMARY KEY CHECK(id=1),maintenance_enabled boolean NOT NULL DEFAULT false,maintenance_start timestamp,maintenance_end timestamp,maintenance_reason varchar,maintenance_message varchar,updated_by varchar,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS version_info(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version varchar NOT NULL UNIQUE,published_at timestamp NOT NULL,content varchar NOT NULL,enabled boolean NOT NULL DEFAULT true,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_history(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,notification_type varchar,destination varchar,result varchar,error_message varchar,sent_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS error_log(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,level varchar NOT NULL,screen varchar,process varchar,message varchar NOT NULL,detail varchar,request_id varchar,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS application_secret(name varchar PRIMARY KEY,secret_value varchar NOT NULL,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auto_login_token(token_hash varchar PRIMARY KEY,user_id varchar NOT NULL,group_id varchar,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_auto_login_token_user ON auto_login_token(user_id);
